17.2 Persistence streams
A persistence stream pairs a byte source/sink with optional persistence hooks. The hook function (phook, with its data pdata) is called for objects that can’t be serialised by value — external pointers and weak references — letting you substitute a placeholder on output and reconstruct the object on input; pass NULL to refuse such objects with an error. The version argument selects the serialisation format version (2, or 3 which supports ALTREP; version 3 output requires R &gt;= 3.6.0 to read).
Note that WRE describes this framework as highly experimental for package use: it may change or be dropped in a future R release. Don’t depend on the fields of the stream structs directly — initialise them with the functions below.
typedef void *R_pstream_data_t;

typedef enum {
  R_pstream_any_format,
  R_pstream_ascii_format,
  R_pstream_binary_format,
  R_pstream_xdr_format,
  R_pstream_asciihex_format
} R_pstream_format_t;

typedef struct R_outpstream_st *R_outpstream_t;
struct R_outpstream_st {
  R_pstream_data_t data;
  R_pstream_format_t type;
  int version;
  void (*OutChar)(R_outpstream_t, int);
  void (*OutBytes)(R_outpstream_t, void *, int);
  SEXP (*OutPersistHookFunc)(SEXP, SEXP);
  SEXP OutPersistHookData;
};

typedef struct R_inpstream_st *R_inpstream_t;
struct R_inpstream_st {
  R_pstream_data_t data;
  R_pstream_format_t type;
  int (*InChar)(R_inpstream_t);
  void (*InBytes)(R_inpstream_t, void *, int);
  SEXP (*InPersistHookFunc)(SEXP, SEXP);
  SEXP InPersistHookData;
};
The connection interface is not available to packages. To allow limited use of connection pointers, defining NEED_CONNECTION_PSTREAMS before including Rinternals.h defines the opaque pointer type:
#ifdef NEED_CONNECTION_PSTREAMS
#ifndef HAVE_RCONNECTION_TYPEDEF
typedef struct Rconn  *Rconnection;
#define HAVE_RCONNECTION_TYPEDEF
#endif
#endif

